import * as THREE from 'three/webgpu';

/**
 * @param {import('@/primitives').NodeConfig} config
 * @param {import('@/primitives').NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ----- geometry & material -----
  const geometry = new THREE.PlaneGeometry(1.6, 1);
  const texture = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');
  texture.colorSpace = THREE.SRGBColorSpace;

  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
  });

  // ----- mesh -----
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, -2.85, 0.2);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // ----- event handlers (none) -----
  mesh.userData.handlers = {};

  // ----- cleanup -----
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
